def transform(grid):
    out = [row[:] for row in grid]
    # Recolor the largest connected 5 object to the key color 9.
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                x,y=q.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]==5 and (a,b) not in seen:
                        seen.add((a,b));q.append((a,b))
            comps.append(comp)
    comp=max(comps,key=len)
    for r,c in comp: out[r][c]=9
    return out

